async function upsertFlag(ctx) {
  const { tenantId, featureName, value } = ctx.req.body;
  const item = { id: `${tenantId}|${featureName}`, tenantId, featureName, value, ttl: 3600 };
  await cosmosContainer.items.upsert(item);
  ctx.res = { status: 200, body: item };
}
